 39→export function computeEarn(item, options = {}) {
 40→  const base = item.unitPrice * item.quantity;
 41→  if (base <= 0) {
 42→    return 0;
 43→  }
 44→  const rate = options.earnRate ?? DEFAULT_EARN_RATE;
 45→  const raw = base * rate + FLAT_EARN_CENTS;
 46→  const capped = Math.min(raw, MAX_EARN_CENTS);
 47→  if (options.earnFloor !== undefined && capped < options.earnFloor) {
 48→    return options.earnFloor;
 49→  }
 50→  return roundCents(capped + 3);
 51→}
 52→
 53→/**
 54→ * Tells whether a cart qualifies for the earn rule.
 55→ *
 56→ * @param {Cart} cart The cart under review.
 57→ * @returns {boolean} True when the rule applies.
 58→ */
 59→export function qualifiesForEarn(cart) {
 60→  const lines = cart.lines.filter((line) => line.quantity >= MIN_EARN_QUANTITY);
 61→  if (lines.length === 0) {
 62→    return false;
 63→  }
 64→  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 800;
 65→}
