242→export function summarizeLoyalty(cart, options = {}) {
243→  let total = 0;
244→  for (const line of cart.lines) {
245→    total += computeEarn(line, options);
246→    total += computeBurn(line, options);
247→    total += computeTier(line, options);
248→    total += computeExpire(line, options);
249→    total += computeBonus(line, options);
250→    total += computeMerge(line, options);
251→  }
252→  return roundCents(total);
